template:
% 参数由系统自动注入：\def\semimajor{3.5} \def\semiminor{2.2} \def\showcenter{1} \def\showaxes{1} \def\showfoci{1} \def\showvertices{1} \def\showpoint{0} \def\pointangle{55} \def\labelp{P}
% 焦点距 c = sqrt(a^2 - b^2)，须 a>b 故 c>0
\pgfmathsetmacro{\focal}{sqrt(\semimajor*\semimajor - \semiminor*\semiminor)}
% 椭圆上点 P 在椭圆方程上：给定角度 theta，半径 r = a*b / sqrt((b*cosθ)^2 + (a*sinθ)^2)
\pgfmathsetmacro{\pc}{cos(\pointangle)}
\pgfmathsetmacro{\ps}{sin(\pointangle)}
\pgfmathsetmacro{\den}{sqrt((\semiminor*\pc)*(\semiminor*\pc) + (\semimajor*\ps)*(\semimajor*\ps))}
\pgfmathsetmacro{\rpx}{\semimajor*\semiminor*\pc/\den}
\pgfmathsetmacro{\rpy}{\semimajor*\semiminor*\ps/\den}
% 视觉归一化：长轴横向缩放到 6cm，保证图形视觉大小稳定。
\pgfmathsetmacro{\figscale}{6 / (2*\semimajor)}
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\pgfmathsetmacro{\loff}{0.34/\figscale}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (O) at (0,0);
  \coordinate (F1) at (-\focal,0);
  \coordinate (F2) at (\focal,0);
  % 长轴/短轴辅助线（先画，垫在椭圆下方）
  \ifnum\showaxes>0
    \draw[dashed, gray] (-\semimajor,0) -- (\semimajor,0);
    \draw[dashed, gray] (0,-\semiminor) -- (0,\semiminor);
  \fi
  % 椭圆曲线
  \draw[thick] (O) ellipse [x radius=\semimajor, y radius=\semiminor];
  % 椭圆上点 P 连两焦点（椭圆定义 PF1+PF2=2a）
  \ifnum\showpoint>0
    \draw[thick] (F1) -- (\rpx,\rpy) -- (F2);
    \fill (\rpx,\rpy) circle [radius=\dotr pt];
    \node at ({1.16*\rpx},{1.16*\rpy}) {$\labelp$};
  \fi
  % 焦点 F1/F2
  \ifnum\showfoci>0
    \fill (F1) circle [radius=\dotr pt];
    \fill (F2) circle [radius=\dotr pt];
    \node[below left=3pt] at (F1) {$F_1$};
    \node[below right=3pt] at (F2) {$F_2$};
  \fi
  % 四个顶点 A1/A2/B1/B2
  \ifnum\showvertices>0
    \fill (-\semimajor,0) circle [radius=\dotr pt];
    \fill (\semimajor,0) circle [radius=\dotr pt];
    \fill (0,-\semiminor) circle [radius=\dotr pt];
    \fill (0,\semiminor) circle [radius=\dotr pt];
    \node[above left=2pt] at (-\semimajor,0) {$A_1$};
    \node[above right=2pt] at (\semimajor,0) {$A_2$};
    \node[below=2pt] at (0,-\semiminor) {$B_1$};
    \node[above=2pt] at (0,\semiminor) {$B_2$};
  \fi
  % 中心 O
  \ifnum\showcenter>0
    \fill (O) circle [radius=\dotr pt];
    \node[below right=2pt] at (O) {$O$};
  \fi
\end{tikzpicture}
